const input = $input.first().json;
const payload = input.body ?? input;
const startedAtMs = Date.now();
const errors = [];

const knownPrisms = new Set([
  'seguranca_psicologica',
  'lideranca_adaptativa',
  'cultura_empreendedora',
  'adaptabilidade_cognitiva',
  'neuroinovacao_prisma',
]);

const knownDimensions = new Set(['S2', 'S4', 'S5A', 'S5B', 'S6', 'S7', 'S8']);

if (payload.contract_version && payload.contract_version !== 'v1') {
  errors.push('contract_version deve ser v1');
}
if (typeof payload.request_id !== 'string' || payload.request_id.trim() === '') {
  errors.push('request_id e obrigatorio');
}
if (typeof payload.form_response_id !== 'string' || payload.form_response_id.trim() === '') {
  errors.push('form_response_id e obrigatorio');
}
if (!Array.isArray(payload.answers) || payload.answers.length === 0) {
  errors.push('answers deve ser uma lista nao vazia');
}

const answers = Array.isArray(payload.answers) ? payload.answers : [];
for (const [index, answer] of answers.entries()) {
  if (typeof answer.question_id !== 'string' || answer.question_id.trim() === '') {
    errors.push(`answers[${index}].question_id e obrigatorio`);
  }
  if (answer.prisma && !knownPrisms.has(answer.prisma)) {
    errors.push(`answers[${index}].prisma inválido: ${answer.prisma}`);
  }
  if (answer.dimensao && !knownDimensions.has(answer.dimensao)) {
    errors.push(`answers[${index}].dimensao inválida: ${answer.dimensao}`);
  }
  const hasScore = typeof answer.score === 'number' && Number.isFinite(answer.score);
  const hasText = typeof answer.answer === 'string' && answer.answer.trim() !== '';
  if (!hasScore && !hasText) {
    errors.push(`answers[${index}] precisa de score numérico ou resposta textual`);
  }
  if (hasScore && (answer.score < 1 || answer.score > 5)) {
    errors.push(`answers[${index}].score deve estar entre 1 e 5`);
  }
}

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      status: 'invalid_payload',
      request_id: payload.request_id ?? null,
      contract_version: 'v1',
      errors,
      metrics: {
        received_at: new Date(startedAtMs).toISOString(),
        n8n_processing_ms: Date.now() - startedAtMs,
      },
    },
  }];
}

return [{
  json: {
    valid: true,
    request: {
      contract_version: 'v1',
      request_id: payload.request_id,
      form_response_id: payload.form_response_id,
      empresa: Boolean(payload.empresa),
      callback_url: payload.callback_url || 'http://backend:8000/api/v1/insights/callback',
      source: payload.source || 'individual_submission',
      answers,
    },
    metrics: {
      received_at: new Date(startedAtMs).toISOString(),
      started_at_ms: startedAtMs,
    },
  },
}];

const data = $input.first().json;
const request = data.request;

const labels = {
  seguranca_psicologica: 'Segurança Psicológica',
  lideranca_adaptativa: 'Liderança Adaptativa',
  cultura_empreendedora: 'Cultura Empreendedora',
  adaptabilidade_cognitiva: 'Adaptabilidade Cognitiva',
  neuroinovacao_prisma: 'Neuroinovação',
};

// Mapeamento das Dimensões (Matriz CREED) para os Prismas
// SP = (S6 + S7)/2, LA = (S7 + S8)/2, CE = (S4 + S6)/2, AC = (S5A + S5B)/2
const dimTotals = {};
const dimCounts = {};
for (const answer of request.answers) {
  if (answer.dimensao && typeof answer.score === 'number') {
    dimTotals[answer.dimensao] = (dimTotals[answer.dimensao] || 0) + answer.score;
    dimCounts[answer.dimensao] = (dimCounts[answer.dimensao] || 0) + 1;
  }
}
const dimAverages = {};
for (const d of Object.keys(dimTotals)) {
  dimAverages[d] = dimTotals[d] / dimCounts[d];
}

// Cálculo dos Prismas a partir das dimensões ou respostas diretas
const prismAverages = {};
if (Object.keys(dimAverages).length > 0) {
  if (dimAverages.S6 && dimAverages.S7) {
    prismAverages.seguranca_psicologica = (dimAverages.S6 + dimAverages.S7) / 2;
  }
  if (dimAverages.S7 && dimAverages.S8) {
    prismAverages.lideranca_adaptativa = (dimAverages.S7 + dimAverages.S8) / 2;
  }
  if (dimAverages.S4 && dimAverages.S6) {
    prismAverages.cultura_empreendedora = (dimAverages.S4 + dimAverages.S6) / 2;
  }
  if (dimAverages.S5A && dimAverages.S5B) {
    prismAverages.adaptabilidade_cognitiva = (dimAverages.S5A + dimAverages.S5B) / 2;
  }
  const allKeys = Object.keys(dimAverages);
  if (allKeys.length === 7) {
    prismAverages.neuroinovacao_prisma = Object.values(dimAverages).reduce((a, b) => a + b, 0) / 7;
  }
}

// Fallback: se as respostas já vieram com 'prisma' direto
for (const answer of request.answers) {
  if (answer.prisma && typeof answer.score === 'number' && !prismAverages[answer.prisma]) {
    prismAverages[answer.prisma] = answer.score;
  }
}

// Formata os prism_scores
const prismScores = Object.entries(labels).map(([key, label]) => ({
  prisma: key,
  label,
  average_score: prismAverages[key] ? Number(prismAverages[key].toFixed(2)) : 3.5,
}));

const ranked = [...prismScores].sort((a, b) => b.average_score - a.average_score);
const strongest = ranked[0];
const opportunity = ranked[ranked.length - 1];

// Estrutura exatamente compatível com o componente ResultadoText do frontend
const destaqueTexto = `A equipe se destaca fortemente na dimensão de ${strongest.label} (média ${strongest.average_score}/5), demonstrando alta capacidade de colaboração e resiliência nas atividades.`;
const oportunidadeTexto = `A dimensão de ${opportunity.label} (média ${opportunity.average_score}/5) apresenta a maior margem de evolução. O desenvolvimento dessa área impulsionará os resultados globais.`;
const analiseTexto = [
  `A análise global da Matriz CREED indica um perfil com forte alinhamento às práticas de ${strongest.label}. Os padrões observados demonstram consistência metodológica nas respostas avaliadas.`,
  `Para manter o equilíbrio neuroinovador, recomenda-se focar na mitigação das fricções apontadas em ${opportunity.label}, promovendo ciclos iterativos de feedback e experimentação.`
];

const recomendacaoTexto = request.empresa ? [
  `Fomentar workshops interdisciplinares voltados ao aprimoramento de ${opportunity.label}.`,
  `Estimular a liderança a abrir espaços formais para experimentação ágil com menor aversão ao erro.`
] : [];

const finishedAtMs = Date.now();

return [{
  json: {
    status: 'completed',
    contract_version: 'v1',
    request_id: request.request_id,
    form_response_id: request.form_response_id,
    source: request.source,
    empresa: request.empresa,
    callback_url: request.callback_url,
    insight: {
      destaque: destaqueTexto,
      oportunidade: oportunidadeTexto,
      analise: analiseTexto,
      recomendacao: recomendacaoTexto,
      prism_scores: prismScores,
      generator: 'creed-ai-v1',
    },
    metrics: {
      received_at: data.metrics.received_at,
      finished_at: new Date(finishedAtMs).toISOString(),
      n8n_processing_ms: finishedAtMs - data.metrics.started_at_ms,
    },
  },
}];
